<template><section class="card mt-7 p-6"><h2 class="text-2xl">Property gallery</h2><p class="mt-2 text-sm text-neutral-600">Upload multiple images or marketing videos. Maximum 100 MB per file.</p><div class="mt-5 flex flex-wrap items-end gap-3"><div class="min-w-0 flex-1"><label class="label">Images and videos</label><input class="input" type="file" multiple accept="image/jpeg,image/png,image/webp,image/avif,video/mp4,video/webm,video/quicktime" @change="chooseFiles"/></div><button type="button" class="btn-primary" :disabled="uploading||!files.length" @click="upload">{{uploading?`Uploading ${progress}…`:`Upload ${files.length||''} Files`}}</button></div><p v-if="message" class="mt-4 rounded-lg bg-success-50 p-3 text-success-800">{{message}}</p><p v-if="errorMessage" class="mt-4 rounded-lg bg-error-50 p-3 text-error-800">{{errorMessage}}</p><div v-if="media.length" class="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><article v-for="item in media" :key="item.id" class="overflow-hidden rounded-xl border"><video v-if="isVideo(item)" :src="item.image_url" class="h-44 w-full bg-black object-contain" controls preload="metadata"/><img v-else :src="item.image_url" :alt="item.alt_text||propertyName" class="h-44 w-full object-cover"/><div class="flex items-center justify-between gap-2 p-3"><span class="text-xs font-semibold uppercase text-neutral-500">{{isVideo(item)?'Video':item.is_primary?'Primary image':'Image'}}</span><div class="flex gap-3"><button v-if="!isVideo(item)&&!item.is_primary" type="button" class="text-sm font-semibold text-primary-700" @click="makePrimary(item)">Make primary</button><button type="button" class="text-sm font-semibold text-error-700" @click="remove(item)">Delete</button></div></div></article></div><p v-else-if="!loading" class="mt-5 text-sm text-neutral-500">No gallery media yet.</p></section></template>
<script setup lang="ts">
import type{PropertyImage}from'~/types/database';const props=defineProps<{propertyId:string;propertyName:string}>(),db=useSupabase(),files=ref<File[]>([]),media=ref<PropertyImage[]>([]),loading=ref(true),uploading=ref(false),progress=ref(''),message=ref(''),errorMessage=ref('');const allowed=new Set(['image/jpeg','image/png','image/webp','image/avif','video/mp4','video/webm','video/quicktime']);const isVideo=(item:PropertyImage)=>item.media_type==='marketing_video'||/\.(mp4|webm|mov)(\?|$)/i.test(item.image_url);async function load(){loading.value=true;const{data,error}=await db.from('property_images').select('*').eq('property_id',props.propertyId).order('sort_order').order('created_at');loading.value=false;if(error){errorMessage.value=error.message;return}media.value=(data||[])as PropertyImage[]}onMounted(load);function chooseFiles(e:Event){files.value=Array.from((e.target as HTMLInputElement).files||[]);errorMessage.value='';const bad=files.value.find(f=>!allowed.has(f.type)||f.size>104857600);if(bad){errorMessage.value=`${bad.name} is not accepted or exceeds 100 MB.`;files.value=[]}}
async function upload(){uploading.value=true;message.value='';errorMessage.value='';try{for(const[index,file]of files.value.entries()){progress.value=`${index+1}/${files.value.length}`;const ext=file.name.split('.').pop()?.toLowerCase()||'bin',path=`${props.propertyId}/${crypto.randomUUID()}.${ext}`;const{error:u}=await db.storage.from('property-media').upload(path,file,{contentType:file.type});if(u)throw u;const{data:url}=db.storage.from('property-media').getPublicUrl(path),video=file.type.startsWith('video/'),primary=!video&&!media.value.some(x=>!isVideo(x)&&x.is_primary);const{error:i}=await db.from('property_images').insert({property_id:props.propertyId,image_url:url.publicUrl,alt_text:video?`${props.propertyName} marketing video`:`${props.propertyName} property image`,media_type:video?'marketing_video':'gallery_image',is_primary:primary,sort_order:media.value.length+index});if(i)throw i;if(primary){const{error:p}=await db.from('properties').update({featured_image:url.publicUrl}).eq('id',props.propertyId);if(p)throw p}}files.value=[];await load();message.value='Gallery media uploaded.'}catch(e:any){errorMessage.value=e.message||'Upload failed.'}finally{uploading.value=false;progress.value=''}}
async function makePrimary(item:PropertyImage){await db.from('property_images').update({is_primary:false}).eq('property_id',props.propertyId);const{error}=await db.from('property_images').update({is_primary:true}).eq('id',item.id);if(error){errorMessage.value=error.message;return}await db.from('properties').update({featured_image:item.image_url}).eq('id',props.propertyId);await load()}async function remove(item:PropertyImage){if(!confirm('Delete this media item?'))return;const marker='/storage/v1/object/public/property-media/',path=item.image_url.includes(marker)?decodeURIComponent(item.image_url.split(marker)[1].split('?')[0]):'';if(path)await db.storage.from('property-media').remove([path]);const{error}=await db.from('property_images').delete().eq('id',item.id);if(error){errorMessage.value=error.message;return}if(item.is_primary){const next=media.value.find(x=>x.id!==item.id&&!isVideo(x));await db.from('properties').update({featured_image:next?.image_url||null}).eq('id',props.propertyId);if(next)await db.from('property_images').update({is_primary:true}).eq('id',next.id)}await load()}
</script>
